// Writes lib/buildInfo.ts: the app version and the moment this bundle was built.
// metro.config.js runs it every time Metro starts, and each release bundle is a fresh Metro run,
// so every build gets its own time. `npm run typecheck` runs it too, so a fresh checkout compiles.
const fs = require('fs');
const path = require('path');

function writeBuildInfo(projectRoot) {
  const appJson = JSON.parse(fs.readFileSync(path.join(projectRoot, 'app.json'), 'utf8'));
  const builtAt = new Date().toISOString();
  const source = [
    '// Generated by scripts/write-build-info.js on every build. Do not edit.',
    'export const BUILD_INFO = {',
    `  version: ${JSON.stringify(appJson.expo.version)},`,
    `  builtAt: ${JSON.stringify(builtAt)},`,
    '} as const;',
    '',
  ].join('\n');
  fs.writeFileSync(path.join(projectRoot, 'lib', 'buildInfo.ts'), source);
}

module.exports = { writeBuildInfo };

if (require.main === module) writeBuildInfo(path.join(__dirname, '..'));
